begin;
create table public.label_artists(id uuid primary key default gen_random_uuid(),label_account_id uuid not null references public.artist_accounts(id) on delete cascade,stage_name text not null check(length(trim(stage_name)) between 2 and 80),contact_email text,phone text,bio text,genres text[] not null default '{}',status text not null default 'ACTIVE' check(status in('ACTIVE','INACTIVE')),linked_artist_account_id uuid references public.artist_accounts(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(label_account_id,stage_name));
create table public.artist_team_invitations(id uuid primary key default gen_random_uuid(),artist_account_id uuid not null references public.artist_accounts(id) on delete cascade,email text not null,membership_role text not null check(membership_role in('ADMIN','MEMBER')),status text not null default 'PENDING' check(status in('PENDING','ACCEPTED','REVOKED','EXPIRED')),invited_by uuid not null references public.profiles(id),token uuid not null default gen_random_uuid() unique,expires_at timestamptz not null default(now()+interval'7 days'),created_at timestamptz not null default now(),unique(artist_account_id,email,status));
alter table public.label_artists enable row level security;alter table public.artist_team_invitations enable row level security;
create policy label_artists_read on public.label_artists for select to authenticated using(public.can_manage_artist(label_account_id) or public.is_admin());
create policy label_artists_manage on public.label_artists for all to authenticated using(public.can_manage_artist(label_account_id) or public.is_admin()) with check(public.can_manage_artist(label_account_id) or public.is_admin());
create policy team_invites_read on public.artist_team_invitations for select to authenticated using(public.can_manage_artist(artist_account_id) or lower(email)=lower(coalesce(auth.jwt()->>'email','')) or public.is_admin());
create policy team_invites_manage on public.artist_team_invitations for all to authenticated using(public.can_manage_artist(artist_account_id) or public.is_admin()) with check(public.can_manage_artist(artist_account_id) or public.is_admin());
grant select,insert,update,delete on public.label_artists,public.artist_team_invitations to authenticated;
create or replace function public.accept_artist_team_invitation(p_token uuid) returns uuid language plpgsql security definer set search_path='' as $$declare i public.artist_team_invitations;p uuid;begin select * into i from public.artist_team_invitations where token=p_token and status='PENDING' and expires_at>now() and lower(email)=lower(coalesce(auth.jwt()->>'email','')) for update;if i.id is null then raise exception'INVITATION_INVALID';end if;p:=public.current_profile_id();insert into public.artist_account_memberships(artist_account_id,profile_id,membership_role)values(i.artist_account_id,p,i.membership_role::public.membership_role)on conflict(artist_account_id,profile_id)do update set membership_role=excluded.membership_role;update public.artist_team_invitations set status='ACCEPTED'where id=i.id;return i.artist_account_id;end$$;
grant execute on function public.accept_artist_team_invitation(uuid) to authenticated;
commit;
